import { createCart } from '../../../api/create-cart/index.js';
import { calculateCart } from '../../../api/calculate-cart/index.js';
import { placeOrder } from '../../../api/place-order/index.js';
import { buildCartRequest } from './buildCartRequest.js';
import { canBook } from './canBook.js';
import { createBookingsForCart } from './createBookingsForCart.js';
import { isCheckoutRequired } from './isCheckoutRequired.js';
import { isDayRangeService } from './dayRange.js';
import { BookResultType, } from './types.js';
export async function executeBookAction(params) {
    if (!canBook({
        serviceSelections: params.serviceSelections,
        formSubmission: params.formSubmission,
    })) {
        throw new Error('Cannot book: missing required data');
    }
    // Step 1: Create booking(s). The helper picks single vs
    // multi-service (DAY-range routing) and returns a uniform
    // { bookingIds, contactDetails } shape.
    const { bookingIds, contactDetails } = await createBookingsForCart(params);
    if (bookingIds.length === 0) {
        throw new Error('Failed to create booking');
    }
    // Step 2: Create cart. `firstSelection` is guaranteed non-empty because
    // `canBook` already enforced `serviceSelections.length > 0` above.
    const firstSelection = params.serviceSelections[0];
    if (!firstSelection) {
        throw new Error('No service selection found');
    }
    const isDayRange = isDayRangeService(firstSelection.service);
    const businessLocationId = isDayRange
        ? // TODO: derive from the selected resource (staff member)'s location
            // once the resource-location work lands. Until then, the DAY-range
            // slot list doesn't reliably carry per-slot location, so we read
            // it from the service's first configured location.
            firstSelection.service.locations?.[0]?._id
        : firstSelection.timeSlot?.location?._id;
    // One cart item per booking ID. Single-day and allDay ranges produce one
    // booking ID; DAY-range expansion produces one per day.
    const cartRequest = buildCartRequest({
        bookingIds,
        contactDetails,
        businessLocationId,
        appId: params.appId,
    });
    const cart = await createCart(cartRequest);
    if (!cart._id) {
        throw new Error('Failed to create cart');
    }
    // Step 3: Calculate cart to get totals (not stored on Cart V2 entity)
    const { cart: calculatedCart, summary } = await calculateCart(cart._id);
    if (!calculatedCart || !summary) {
        throw new Error('Failed to calculate cart');
    }
    // Step 4: Determine if checkout is required or can be skipped. For
    // DAY-range expansion all N bookings are the same service, so reading the
    // first selection's service is still correct.
    const service = firstSelection.service;
    if (isCheckoutRequired(calculatedCart, summary, service)) {
        return { type: BookResultType.CheckoutRequired, cartId: cart._id };
    }
    // Step 5: Skip checkout — place order directly
    const orderResponse = await placeOrder(cart._id);
    const orderId = orderResponse.orderId;
    if (!orderId) {
        throw new Error('Failed to place order');
    }
    return { type: BookResultType.CheckoutSkipped, orderId };
}
